local UIWorldBossBuffNode = Class('UIWorldBossBuffNode')

function UIWorldBossBuffNode:__init()
    self._data = nil
end

function UIWorldBossBuffNode:__delete()
    self._data = nil
end

function UIWorldBossBuffNode:Awake()
    
end

function UIWorldBossBuffNode:Refresh(data)
    if not data then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end

    self._data = data   --类型vo

    self:FillBuffInfo()
    KTool.SetActive(self.controller.gameObject, true)
end

function UIWorldBossBuffNode:FillBuffInfo()
    CfUtils.FillText(self.TxtItemName, self._data.name)
    CfUtils.FillImage(self.ImgIcon, self._data.icon)


    local buffs = worldBossComponent:GetCurBossBuffs()
    local num = 0
    for k, v in pairs(buffs) do
        if checkNumber(v.type) == checkNumber(self._data.type) then
            num = num + 1
        end
    end

    CfUtils.FillText(self.TxtCountNum, "x"..num)

    local status = num > 0 and 2 or 1
    KTool.SetActive(self.ActiveBg, num > 0)
    CfUtils.SetUISwitchImage(self.ImgIcon, status)
    CfUtils.SetUISwitchText(self.TxtItemName, status)
    CfUtils.SetUISwitchText(self.TxtCountNum, status)

    --最多三个
    for i = 1, 3 do
        local go = self.DescLayout.transform:Find("DescCell"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.DescCell, self.DescLayout)
            go.name = "DescCell"..i
        end

        CfUtils.SetUISwitchImage(go.transform:Find("ImgIcon"), i <= num and 2 or 1)
        CfUtils.SetUISwitchImage(go.transform:Find("ImgLine"), i <= num and 2 or 1)
        CfUtils.SetUISwitchText(go.transform:Find("TxtDescribe"), i <= num and 2 or 1)

        KTool.SetActive(go.transform:Find("ActiveBg"), i <= num)

        local id = CfUtils.GetStringIdGroupData(string.format("%s".."IDGroup",AutoIds.IdSetting972), self._data.type.."_"..i)
        local vo = QuestConfMgr:GetInstance():GetWorldBossBuffVo(id)
        if vo then
            CfUtils.FillText(go.transform:Find("TxtDescribe"), vo.desc)
        end
        KTool.SetActive(go, true)
    end

    --[[
    local _t = CfUtils.Split(data.icon)
    if not _t then 
        return
    end

    for i = 1, #_t do
        local go = self.LogisticsGroup.transform:Find("buff"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgLogisticsBg, self.LogisticsGroup)
            go.name = "buff"..i
        end

        local iconPath = CS.ParseUtils.ParsePathNameByData(_t[i])
        CfUtils.FillImage(go.transform:Find("Icon"), iconPath)
        KTool.SetActive(go, true)
    end
    ]]
end


function UIWorldBossBuffNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWorldBossBuffNode
